; rotor4_test.asm - generated by make_rotor4_test.py: three helicopters flying sideways, a still body and four
; pizza-slice blades on top spinning at 2, 5 and 9 / 64 turns per frame.
; Build: lwasm --format=raw -o rotor4_test_raw.bin rotor4_test.asm, then pad to 32768 bytes with $FF.

Wait_Recal      equ $F192
Intensity_a     equ $F2AB
Moveto_d        equ $F312
Draw_Line_d     equ $F3DF
Reset0Ref       equ $F354
Vec_Misc_Count  equ $C823

Angles          equ $C880           ; one byte per rotor
Blade           equ $C884           ; the blade's angle now
Count           equ $C885
Pos             equ $C888           ; the helicopters' sideways place, moving 1 per frame

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "ROTOR TEST 4"
        fcb     $80
        fcb     0

Start:
        clr     Angles
        clr     Angles+1
        clr     Angles+2
        clr     Pos
Main:
        jsr     Wait_Recal
        lda     #$7F
        jsr     Intensity_a
        inc     Pos
; helicopter 0
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #40
        ldb     #-70
        addb    Pos
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        jsr     Body
        lda     Angles+0
        adda    #2
        anda    #63
        sta     Angles+0
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
; helicopter 1
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #40
        ldb     #70
        addb    Pos
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        jsr     Body
        lda     Angles+1
        adda    #5
        anda    #63
        sta     Angles+1
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
; helicopter 2
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #-55
        ldb     #0
        addb    Pos
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        jsr     Body
        lda     Angles+2
        adda    #9
        anda    #63
        sta     Angles+2
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
        jmp     >Main               ; (extended: Main sits below $100 and DP is $D0)

; the still body from the hub, back to the hub
Body:
        lda     #-12
        ldb     #-35
        jsr     Moveto_d
        lda     #0
        ldb     #70
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #24
        ldb     #0
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #0
        ldb     #-70
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #-24
        ldb     #0
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #12
        ldb     #0
        jsr     Moveto_d
        lda     #0
        ldb     #-60
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #10
        ldb     #-10
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     #-10
        ldb     #105
        jsr     Moveto_d
        rts

; four pizza-slice blades from the hub: out along one side, across the tip, back along the other side
Rotor:
        lda     Blade
        lsla
        ldx     #Side1
        leax    a,x
        ldd     ,x
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     Blade
        lsla
        ldx     #Edge
        leax    a,x
        ldd     ,x
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     Blade
        lsla
        ldx     #Side2
        leax    a,x
        ldd     ,x
        clr     Vec_Misc_Count
        jsr     Draw_Line_d
        lda     Blade
        adda    #16
        anda    #63
        sta     Blade
        dec     Count
        bne     Rotor
        rts

